// A course to plan (new, or Plan again): the app's bot (Coach) plans it from what the person wants to learn, their
// language and level, what to change and the course so far, into its plan.
const TASK = "Plan a complete, fun programming course that teaches the person the language they chose, for what they want to do, at their level, step by step from easy to harder. Answer only in this format, one item a line, no other text:\nCOURSE: <one emoji> <a short, catchy course title>\nUNIT: <one emoji> <unit title> | <one line on what the unit covers>\nLESSON: <one emoji> <lesson title> | <one line: the one thing they'll learn and the function they'll write, like: write is_even(n)>\nGive 3 or 4 units, each with 2 or 3 lessons, at most 10 lessons in all; every LESSON line belongs to the UNIT line above it. Every lesson ends with a small exercise: writing one function. Someone who has never programmed starts with values, printing, variables and simple functions, one idea a lesson; someone who knows a little starts with lists, loops and dictionaries; someone quite good gets real problems (text, data, algorithms). If the course so far is given, change it only as asked and keep the exact titles of the lessons that stay.";
function changedIds(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  return ids;
}

function planText(course, units, lessons) {
  const lines = ["Language: " + course.language, "What I want to learn and do: " + course.goal];
  if (course.level) lines.push("How much I know already: " + course.level);
  if (course.changes) lines.push("What to change this time: " + course.changes);
  if (lessons.length) {
    lines.push("The course so far (keep the exact titles of the lessons that stay):");
    for (const unit of units) {
      lines.push("UNIT: " + unit.title + " | " + (unit.about || ""));
      for (const lesson of lessons.filter((entry) => entry.unit === unit.id)) lines.push("LESSON: " + lesson.title + " | " + (lesson.goal || ""));
    }
  }
  return lines.join("\n").slice(0, 7900);
}

async function main(input) {
  for (const id of changedIds(input)) {
    const course = await records.get("prog_courses", id);
    if (!course || course.status !== "Planning") continue;
    const units = await records.list("prog_units", { where: "=course == params.course", params: { course: id }, sort: "position", limit: 100 });
    const lessons = await records.list("prog_lessons", { where: "=course == params.course && status != \"Put away\"", params: { course: id }, sort: "position", limit: 100 });
    await records.update("prog_courses", id, { plan: "", note: "" });
    await ai.work({ bot: "default", task: TASK, items: [{ record: { table: "prog_courses", id }, text: planText(course, units, lessons) }], into: "plan" });
    return { planning: id };
  }
  return { planning: null };
}

// The bot's plan made into units and lessons. A lesson or unit whose title stays the same (emoji, case and punctuation
// aside) is kept with its text, exercise and everyone's progress, moved to its new place; a new one is to be written; one
// the plan leaves out is put away.
function changedIds(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  return ids;
}
const keyOf = (title) => String(title || "").toLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").trim();

function parsePlan(text) {
  const plan = { title: "", units: [] };
  for (const raw of String(text || "").split("\n")) {
    const line = raw.replace(/^[\s*#>-]+/, "").replace(/\*\*/g, "").trim();
    const found = /^(COURSE|UNIT|LESSON)\s*:\s*(.+)$/i.exec(line);
    if (!found) continue;
    const [title = "", second = ""] = found[2].split("|").map((part) => part.trim());
    const kind = found[1].toUpperCase();
    if (kind === "COURSE") plan.title = title.slice(0, 200);
    else if (kind === "UNIT" && title) plan.units.push({ title: title.slice(0, 200), about: second.slice(0, 300), lessons: [] });
    else if (kind === "LESSON" && title && plan.units.length) plan.units[plan.units.length - 1].lessons.push({ title: title.slice(0, 200), goal: second.slice(0, 300) });
  }
  plan.units = plan.units.filter((unit) => unit.lessons.length).slice(0, 6);
  return plan;
}

const byKey = (rows) => {
  const map = new Map();
  for (const row of rows) map.set(keyOf(row.title), [...(map.get(keyOf(row.title)) || []), row]);
  return map;
};
const take = (left, title) => {
  const found = left.get(keyOf(title));
  return found && found.length ? found.shift() : null;
};

async function main(input) {
  const built = [];
  for (const id of changedIds(input)) {
    const course = await records.get("prog_courses", id);
    if (!course || !course.plan) continue;
    const plan = parsePlan(course.plan);
    if (!plan.units.length) {
      await records.update("prog_courses", id, { status: "Problem", note: "The plan came back in a shape I can't use. Press Plan again." });
      continue;
    }
    const units = byKey(await records.list("prog_units", { where: "=course == params.course", params: { course: id }, limit: 100 }));
    const lessons = byKey(await records.list("prog_lessons", { where: "=course == params.course && status != \"Put away\"", params: { course: id }, limit: 100 }));
    let writing = 0;
    let kept = 0;
    let stillWriting = 0;
    for (let place = 0; place < plan.units.length; place += 1) {
      const spec = plan.units[place];
      const position = place + 1;
      let unit = take(units, spec.title);
      if (!unit) unit = await records.create("prog_units", { course: id, title: spec.title, about: spec.about, position });
      else if (unit.position !== position) await records.update("prog_units", unit.id, { position });
      for (let step = 0; step < spec.lessons.length; step += 1) {
        const wanted = spec.lessons[step];
        const at = position * 100 + step + 1;
        const same = take(lessons, wanted.title);
        if (!same) {
          await records.create("prog_lessons", { course: id, unit: unit.id, position: at, title: wanted.title, goal: wanted.goal, status: "Writing", fixes: 0 });
          writing += 1;
          continue;
        }
        kept += 1;
        if (same.status === "Writing" || same.status === "Fixing") stillWriting += 1;
        if (same.unit !== unit.id || same.position !== at) await records.update("prog_lessons", same.id, { unit: unit.id, position: at });
      }
    }
    for (const rows of units.values()) for (const row of rows) await records.markObsolete("prog_units", row.id);
    const leftOut = [...lessons.values()].flat();
    for (const row of leftOut) await records.update("prog_lessons", row.id, { status: "Put away" });
    const status = writing + stillWriting ? "Writing" : "Ready";
    await records.update("prog_courses", id, { title: plan.title || course.title || course.goal.slice(0, 80), status, changes: "", note: "" });
    built.push({ course: id, units: plan.units.length, writing, kept, putAway: leftOut.length, status });
  }
  return { built };
}

// Lessons to write (new ones, and ones someone asked to write again): the app's bot writes each with its quiz and its
// exercise (starting code, a solution and the tests), following the format and the rules of tests for its language.
// verify_lessons runs the solution against the tests on the computer before the lesson is ready.
const TASK = "Write one short, fun lesson of a programming course for the person learning it, with a quiz and a small coding exercise with its starting code, a solution and the tests that check it. Follow the format and the rules in the text exactly: the app runs your solution against your tests on a computer, and the lesson is only ready once every test passes. Answer only in that format.";
const FORMAT = "Answer in exactly this format, each marker alone on its line, nothing before LESSON or after END, and no markdown code fences anywhere:\nLESSON\n(3 to 6 short paragraphs, at most 300 words, plain text, friendly and clear; show one tiny example of code, each of its lines starting with 4 spaces)\nQUIZ\n(3 questions on the lesson, each exactly: a line Q: the question, then lines A:, B:, C:, D: with one choice each, then ANSWER: the right letter, then WHY: one short sentence. Only one choice is right; vary which letter.)\nEXERCISE\n(2 to 4 sentences for the learner: the one function to write, its exact name and arguments, what it returns, and one example call with its result)\nSTARTER\n(the code they start from: the function's first line, a comment saying what to do, and a placeholder return that does NOT pass the tests)\nSOLUTION\n(a correct, simple solution, written the way a learner at this level would)\nTESTS\n(the test file, following the rules below)\nEND";
const TEST_RULES = {"Python":"Rules for the code and tests (Python): the exercise is ONE function with a clear name. STARTER and SOLUTION define it with def. TESTS starts with the line: from solution import *\nthen 3 to 6 test functions, each named test_<what it checks in words, with underscores> and taking no arguments, each checking one thing with plain assert and a message that says what was expected, like: assert double(2) == 4, \"double(2) should be 4\". Test the normal cases from the exercise and one edge case (an empty list, zero, a negative number) the EXERCISE mentions. Compare floats with round(x, 2). Use only the standard library; no input(), no files, no network, no printing, no randomness; each test takes well under a second. The SOLUTION must pass every test and the STARTER must fail at least one.","JavaScript":"Rules for the code and tests (JavaScript): the exercise is ONE function with a clear name, written as function name(args) { ... } in STARTER and SOLUTION (never const name = ...). TESTS has 3 to 6 tests, each exactly: test(\"what it checks, in words\", () => { expect(value).toBe(expected); }); Available in tests: expect(x).toBe(y) (numbers, text, true/false), expect(x).toEqual(y) (lists and objects), expect(x).toBeCloseTo(y) (decimals), expect(x).toBeTruthy(), expect(x).toBeFalsy(), expect(x).toContain(y), expect(() => f()).toThrow(), and assert(condition, \"message\"). Test the normal cases from the exercise and one edge case (an empty list, zero, a negative number) the EXERCISE mentions. No require or import, no prompt(), no files, no network, no console.log, no Math.random; each test takes well under a second. The SOLUTION must pass every test and the STARTER must fail at least one."};
function changedIds(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  return ids;
}

function lessonText(course, unit, lesson, before) {
  return [
    "The course: " + (course.title || course.goal) + ", in " + course.language + ", for someone who wants to: " + course.goal + (course.level ? " (" + course.level + ")" : ""),
    "Unit: " + (unit ? unit.title + (unit.about ? " - " + unit.about : "") : ""),
    "This lesson: " + lesson.title,
    "They will learn: " + (lesson.goal || lesson.title),
    ...(before.length ? ["Lessons before it (they know these): " + before.join("; ")] : ["This is the first lesson."]),
    ...(lesson.request ? ["Change this time: " + lesson.request] : []),
    "",
    FORMAT,
    "",
    TEST_RULES[course.language] || TEST_RULES.Python
  ].join("\n").slice(0, 7900);
}

async function main(input) {
  const courses = {};
  const items = [];
  for (const id of changedIds(input)) {
    const lesson = await records.get("prog_lessons", id);
    if (!lesson || lesson.status !== "Writing") continue;
    if (!(lesson.course in courses)) {
      courses[lesson.course] = {
        course: await records.get("prog_courses", lesson.course),
        lessons: await records.list("prog_lessons", { where: "=course == params.course && status != \"Put away\"", params: { course: lesson.course }, sort: "position", limit: 100 }),
        units: await records.list("prog_units", { where: "=course == params.course", params: { course: lesson.course }, limit: 100 })
      };
    }
    const { course, lessons, units } = courses[lesson.course];
    if (!course) continue;
    const before = lessons.filter((entry) => entry.position < lesson.position).map((entry) => entry.title + (entry.goal ? " (" + entry.goal + ")" : ""));
    items.push({ record: { table: "prog_lessons", id }, text: lessonText(course, units.find((unit) => unit.id === lesson.unit), lesson, before) });
  }
  if (items.length) await ai.work({ bot: "default", task: TASK, items: items.slice(0, 100), into: "material" });
  return { writing: items.length };
}

// No lesson ships with broken tests: once the bot has written one (its material), its solution runs against its tests
// on the computer, and so does its starting code, which must fail one. Passing, the lesson is ready (its text, exercise,
// code and quiz on it); failing, the bot fixes it with what the computer said, at most FIXES times, then the lesson shows
// a problem and can be written again. A course whose lessons are all ready is ready.
const FIXES = 2;
const TASK = "Your solution and tests for a programming exercise didn't work on the computer: the text says what it said. Find the mistake (in the solution, the tests or both, and make sure the starting code fails at least one test) and answer with the whole lesson again, fixed, in exactly the same format and following the same rules.";
const FORMAT = "Answer in exactly this format, each marker alone on its line, nothing before LESSON or after END, and no markdown code fences anywhere:\nLESSON\n(3 to 6 short paragraphs, at most 300 words, plain text, friendly and clear; show one tiny example of code, each of its lines starting with 4 spaces)\nQUIZ\n(3 questions on the lesson, each exactly: a line Q: the question, then lines A:, B:, C:, D: with one choice each, then ANSWER: the right letter, then WHY: one short sentence. Only one choice is right; vary which letter.)\nEXERCISE\n(2 to 4 sentences for the learner: the one function to write, its exact name and arguments, what it returns, and one example call with its result)\nSTARTER\n(the code they start from: the function's first line, a comment saying what to do, and a placeholder return that does NOT pass the tests)\nSOLUTION\n(a correct, simple solution, written the way a learner at this level would)\nTESTS\n(the test file, following the rules below)\nEND";
const TEST_RULES = {"Python":"Rules for the code and tests (Python): the exercise is ONE function with a clear name. STARTER and SOLUTION define it with def. TESTS starts with the line: from solution import *\nthen 3 to 6 test functions, each named test_<what it checks in words, with underscores> and taking no arguments, each checking one thing with plain assert and a message that says what was expected, like: assert double(2) == 4, \"double(2) should be 4\". Test the normal cases from the exercise and one edge case (an empty list, zero, a negative number) the EXERCISE mentions. Compare floats with round(x, 2). Use only the standard library; no input(), no files, no network, no printing, no randomness; each test takes well under a second. The SOLUTION must pass every test and the STARTER must fail at least one.","JavaScript":"Rules for the code and tests (JavaScript): the exercise is ONE function with a clear name, written as function name(args) { ... } in STARTER and SOLUTION (never const name = ...). TESTS has 3 to 6 tests, each exactly: test(\"what it checks, in words\", () => { expect(value).toBe(expected); }); Available in tests: expect(x).toBe(y) (numbers, text, true/false), expect(x).toEqual(y) (lists and objects), expect(x).toBeCloseTo(y) (decimals), expect(x).toBeTruthy(), expect(x).toBeFalsy(), expect(x).toContain(y), expect(() => f()).toThrow(), and assert(condition, \"message\"). Test the normal cases from the exercise and one edge case (an empty list, zero, a negative number) the EXERCISE mentions. No require or import, no prompt(), no files, no network, no console.log, no Math.random; each test takes well under a second. The SOLUTION must pass every test and the STARTER must fail at least one."};
const RUN = {
  Python: { solution: "solution.py", tests: "test_lesson.py", command: "python3 ../harness/run.py" },
  JavaScript: { solution: "solution.js", tests: "test_lesson.js", command: "node ../harness/run.js" }
};
function changedIds(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  return ids;
}
// A lesson's answer in its sections (LESSON, QUIZ, EXERCISE, STARTER, SOLUTION, TESTS), code fences taken away.
function sectionsOf(material) {
  const out = {};
  let at = null;
  for (const raw of String(material || "").replace(/\r/g, "").split("\n")) {
    const marker = /^[\s*#]*(LESSON|QUIZ|EXERCISE|STARTER|SOLUTION|TESTS|END)[\s*:#]*$/.exec(raw);
    if (marker) {
      at = marker[1] === "END" ? null : marker[1];
      if (at) out[at] = [];
      continue;
    }
    if (at && !/^\s*```/.test(raw)) out[at].push(raw);
  }
  const text = (key) => (out[key] || []).join("\n").replace(/^\n+|\s+$/g, "");
  return { lesson: text("LESSON"), quiz: text("QUIZ"), exercise: text("EXERCISE"), starter: text("STARTER"), solution: text("SOLUTION"), tests: text("TESTS") };
}

function questionsOf(quiz) {
  const questions = [];
  let question = null;
  for (const raw of String(quiz || "").split("\n")) {
    const line = raw.replace(/^[\s*#>-]+/, "").replace(/\*\*/g, "").trim();
    let found;
    if ((found = /^Q(?:uestion)?\s*\d*\s*[:.)]\s*(.+)$/i.exec(line))) {
      question = { question: found[1], choices: {}, answer: "", why: "" };
      questions.push(question);
    } else if (!question) {
      continue;
    } else if ((found = /^ANSWER\s*[:.)-]?\s*\(?([ABCD])\b/i.exec(line))) {
      question.answer = found[1].toUpperCase();
    } else if ((found = /^WHY\s*[:.)-]?\s*(.+)$/i.exec(line))) {
      question.why = found[1];
    } else if ((found = /^\(?([ABCD])\s*[:.)]\s*(.+)$/i.exec(line))) {
      question.choices[found[1].toUpperCase()] = found[2];
    }
  }
  return questions.filter((entry) => entry.question && entry.answer && ["A", "B", "C", "D"].every((letter) => entry.choices[letter])).slice(0, 5);
}

/** The solution against the tests, then the starting code: what the computer said, or why it isn't ready. */
async function verify(lesson, parts, language) {
  const missing = ["lesson", "exercise", "starter", "solution", "tests"].filter((key) => !parts[key]);
  if (missing.length) return { ok: false, said: "The answer had no " + missing.join(", ") + " section." };
  const run = RUN[language] || RUN.Python;
  const files = { ["solution/" + run.solution]: parts.solution, ["solution/" + run.tests]: parts.tests, ["start/" + run.solution]: parts.starter, ["start/" + run.tests]: parts.tests };
  const command = "cd solution && " + run.command + "; echo \"SOLUTION EXIT $?\"; cd ../start && " + run.command + " > /dev/null; echo \"START EXIT $?\"";
  const result = await computer.run({ command, files, seconds: 30 });
  const solutionExit = (/SOLUTION EXIT (\d+)/.exec(result.output) || [])[1];
  const startExit = (/START EXIT (\d+)/.exec(result.output) || [])[1];
  const said = result.output.replace(/\n?(SOLUTION|START) EXIT \d+/g, "").trim();
  if (result.timedOut) return { ok: false, said: said + "\nIt ran for more than 30 seconds and was stopped." };
  if (solutionExit !== "0") return { ok: false, said: "The solution didn't pass the tests:\n" + said };
  if (startExit === "0") return { ok: false, said: "The starting code passes every test already, so the tests don't check the exercise:\n" + said };
  return { ok: true, said };
}

async function main(input) {
  const ids = changedIds(input);
  // Any lesson written while this job wasn't told (more than one run's worth at once), so none waits for ever.
  for (const lesson of await records.list("prog_lessons", { where: "=(status == \"Writing\" || status == \"Fixing\") && material != \"\"", limit: 10 })) {
    if (!ids.includes(lesson.id)) ids.push(lesson.id);
  }
  const courses = {};
  const fixes = [];
  const done = { ready: [], fixing: [], problem: [] };
  for (const id of ids.slice(0, 10)) {
    const lesson = await records.get("prog_lessons", id);
    if (!lesson || !lesson.material || !["Writing", "Fixing"].includes(lesson.status)) continue;
    if (!(lesson.course in courses)) courses[lesson.course] = await records.get("prog_courses", lesson.course);
    const course = courses[lesson.course];
    if (!course) continue;
    const parts = sectionsOf(lesson.material);
    const { ok, said } = await verify(lesson, parts, course.language);
    if (ok) {
      for (const old of await records.list("prog_questions", { where: "=lesson == params.lesson", params: { lesson: id }, limit: 20 })) await records.markObsolete("prog_questions", old.id);
      const questions = questionsOf(parts.quiz);
      for (let index = 0; index < questions.length; index += 1) {
        const entry = questions[index];
        await records.create("prog_questions", { lesson: id, position: index + 1, question: entry.question.slice(0, 1000), choice_a: entry.choices.A.slice(0, 500), choice_b: entry.choices.B.slice(0, 500), choice_c: entry.choices.C.slice(0, 500), choice_d: entry.choices.D.slice(0, 500), answer: entry.answer, why: entry.why.slice(0, 1000) });
      }
      await records.update("prog_lessons", id, { status: "New", text: parts.lesson, exercise: parts.exercise, starter: parts.starter, solution: parts.solution, tests: parts.tests, check: said.slice(0, 20000), request: "" });
      done.ready.push(id);
    } else if ((lesson.fixes || 0) < FIXES) {
      fixes.push({ id, text: ("The lesson you wrote:\n" + lesson.material.slice(0, 5000) + "\n\nWhat the computer said:\n" + said.slice(0, 1200) + "\n\n" + FORMAT + "\n\n" + (TEST_RULES[course.language] || TEST_RULES.Python)).slice(0, 7900), fixes: (lesson.fixes || 0) + 1, said });
    } else {
      await records.update("prog_lessons", id, { status: "Problem", check: said.slice(0, 20000), material: "" });
      done.problem.push(id);
    }
  }
  if (fixes.length) {
    // One batch for every lesson to fix; when the bot is busy, they wait for the next lesson the job hears of.
    let queued = true;
    try {
      await ai.work({ bot: "default", task: TASK, items: fixes.map((fix) => ({ record: { table: "prog_lessons", id: fix.id }, text: fix.text })), into: "material" });
    } catch (error) {
      queued = false;
      console.log("Fixing waits: " + error.message);
    }
    if (queued) {
      for (const fix of fixes) {
        await records.update("prog_lessons", fix.id, { status: "Fixing", fixes: fix.fixes, check: fix.said.slice(0, 20000), material: "" });
        done.fixing.push(fix.id);
      }
    }
  }
  for (const courseId of Object.keys(courses)) {
    const waiting = await records.list("prog_lessons", { where: "=course == params.course && (status == \"Writing\" || status == \"Fixing\")", params: { course: courseId }, limit: 1 });
    if (!waiting.length && courses[courseId] && courses[courseId].status === "Writing") await records.update("prog_courses", courseId, { status: "Ready" });
  }
  return done;
}

// A lesson's page shows the person's own progress in it (each person's own), made the first time with the lesson's
// starting code. With a course and no lesson, the first ready lesson they haven't done.
async function main(input) {
  let lessonId = String((input && input.lesson) || "");
  if (!lessonId && input && input.course) {
    const course = String(input.course);
    const lessons = await records.list("prog_lessons", { where: "=course == params.course && status == \"New\"", params: { course }, sort: "position", limit: 100 });
    const done = new Set((await records.list("prog_progress", { where: "=course == params.course && done == true", params: { course }, limit: 100 })).map((row) => row.lesson));
    const next = lessons.find((row) => !done.has(row.id));
    if (!next) return { notify: lessons.length ? "You've done every lesson of this course! 🏆" : "Its lessons are still being written." };
    lessonId = next.id;
  }
  const lesson = await records.get("prog_lessons", lessonId);
  if (!lesson) return { notify: "That lesson is no longer there." };
  if (lesson.status !== "New") return { notify: "That lesson isn't ready yet." };
  const [mine] = await records.list("prog_progress", { where: "=lesson == params.lesson", params: { lesson: lesson.id }, limit: 1 });
  const id = mine ? mine.id : (await records.create("prog_progress", { course: lesson.course, lesson: lesson.id, code: lesson.starter, done: false, tries: 0 })).id;
  return { go: { screen: "lesson", params: { id: lesson.id, mine: id } } };
}

// "Check my answer": the person's code and the lesson's tests run on the computer. The attempt (each person's own)
// keeps their code and what the tests said; their progress keeps their code and whether they've done it. A failure goes
// to the app's bot, which explains it in plain words into the attempt (when the app may use AI and the bot isn't busy).
const TASK = "A learner's code didn't pass a programming exercise; the text has the exercise, their code and what the tests said. In 2 to 4 short, kind sentences in plain words, explain what went wrong and give one hint for fixing it. Don't write the corrected code for them. No markdown.";
const RUN = {
  Python: { solution: "solution.py", tests: "test_lesson.py", command: "python3 ../harness/run.py" },
  JavaScript: { solution: "solution.js", tests: "test_lesson.js", command: "node ../harness/run.js" }
};

async function main(input) {
  const mine = await records.get("prog_progress", String(input.mine));
  if (!mine) return { notify: "That lesson's progress is no longer there." };
  const lesson = await records.get("prog_lessons", mine.lesson);
  const course = lesson && (await records.get("prog_courses", lesson.course));
  if (!lesson || !course || !lesson.tests) return { notify: "That lesson has no tests yet." };
  const code = String(input.code ?? mine.code ?? "");
  const run = RUN[course.language] || RUN.Python;
  const result = await computer.run({ command: "cd lesson && " + run.command, files: { ["lesson/" + run.solution]: code, ["lesson/" + run.tests]: lesson.tests }, seconds: 15 });
  const passed = result.exitCode === 0 && !result.timedOut;
  const output = (result.timedOut ? result.output + "\n⏱️ Your code ran for more than 15 seconds, so it was stopped: is there a loop that never ends?" : result.output).slice(0, 20000);
  const attempt = await records.create("prog_attempts", { lesson: lesson.id, code, passed, output, at: new Date().toISOString() });
  await records.update("prog_progress", mine.id, { code, done: passed || mine.done === true, tries: (mine.tries || 0) + 1, last: attempt.id, ...(passed && !mine.done ? { finished: new Date().toISOString() } : {}) });
  if (passed) return { celebrate: "🎉 Every test passed!" };
  let explaining = true;
  try {
    await ai.work({ bot: "default", task: TASK, items: [{ record: { table: "prog_attempts", id: attempt.id }, text: ("The exercise: " + lesson.exercise + "\n\nTheir code:\n" + code.slice(0, 4000) + "\n\nWhat the tests said:\n" + output.slice(0, 2500)).slice(0, 7900) }], into: "explanation" });
  } catch (error) {
    explaining = false;
  }
  const last = output.trim().split("\n").pop() || "";
  return { notify: (/tests passed/.test(last) ? last : "Not yet.") + (explaining ? " Coach is looking at what went wrong…" : " See below what the tests said.") };
}

// The person's first answer to a question, kept as their own with whether it's right.
async function main(input) {
  const question = await records.get("prog_questions", String(input.question));
  if (!question) return { notify: "That question is no longer there." };
  const [had] = await records.list("prog_answers", { where: "=question == params.question", params: { question: question.id }, limit: 1 });
  if (had) return {};
  const pick = String(input.pick || "");
  await records.create("prog_answers", { lesson: question.lesson, question: question.id, picked: pick, correct: pick === question.answer });
  return {};
}

// The quiz, one question at a time: the first the person hasn't answered, or back to the lesson. Again puts their
// answers away (kept, not counted) and starts from the first question.
async function main(input) {
  const lesson = String(input.lesson);
  const questions = await records.list("prog_questions", { where: "=lesson == params.lesson", params: { lesson }, sort: "position", limit: 20 });
  if (!questions.length) return { notify: "This lesson has no quiz." };
  const answers = await records.list("prog_answers", { where: "=lesson == params.lesson", params: { lesson }, limit: 40 });
  if (input.again) for (const answer of answers) await records.markObsolete("prog_answers", answer.id);
  const answered = new Set(input.again ? [] : answers.map((row) => row.question));
  const question = questions.find((row) => !answered.has(row.id));
  return question ? { go: { screen: "quiz", params: { lesson, id: question.id, mine: String(input.mine || "") } } } : { go: { screen: "lesson", params: { id: lesson, mine: String(input.mine || "") } } };
}

