// Runs a lesson's tests on the computer: node harness/run.js
// solution.js is the code being checked (its functions written as `function name(…) { … }`); test_lesson.js has the
// lesson's tests, each test("what it checks", () => { … }) using expect(value).toBe(…), .toEqual(…), .toBeCloseTo(…),
// .toThrow() or assert(condition, message), and the solution's functions by name. Every test runs, even after one fails.
const fs = require("node:fs");
const util = require("node:util");
const vm = require("node:vm");

const shown = (value) => util.inspect(value, { depth: 4, breakLength: Infinity });
const deepEqual = (a, b) => util.isDeepStrictEqual(a, b);

function expect(actual) {
  const fail = (message) => {
    throw Object.assign(new Error(message), { name: "TestFailure" });
  };
  return {
    toBe: (expected) => Object.is(actual, expected) || fail(`expected ${shown(expected)}, got ${shown(actual)}`),
    toEqual: (expected) => deepEqual(JSON.parse(JSON.stringify(actual ?? null)), JSON.parse(JSON.stringify(expected ?? null))) || fail(`expected ${shown(expected)}, got ${shown(actual)}`),
    toBeCloseTo: (expected, digits = 2) => Math.abs(actual - expected) < 10 ** -digits / 2 || fail(`expected about ${shown(expected)}, got ${shown(actual)}`),
    toBeTruthy: () => Boolean(actual) || fail(`expected something true, got ${shown(actual)}`),
    toBeFalsy: () => !actual || fail(`expected something false, got ${shown(actual)}`),
    toContain: (item) => (actual?.includes?.(item) ?? false) || fail(`expected ${shown(actual)} to contain ${shown(item)}`),
    toThrow: () => {
      try {
        actual();
      } catch {
        return true;
      }
      return fail("expected it to throw an error, and it didn't");
    }
  };
}

function main() {
  const tests = [];
  const context = vm.createContext({
    console,
    test: (name, run) => tests.push({ name: String(name), run }),
    expect,
    assert: (condition, message = "this wasn't true") => {
      if (!condition) throw Object.assign(new Error(message), { name: "TestFailure" });
    }
  });
  try {
    vm.runInContext(fs.readFileSync("solution.js", "utf8"), context, { filename: "solution.js", timeout: 5000 });
  } catch (error) {
    console.log(error?.name === "SyntaxError"
      ? `❌ JavaScript can't read the code: ${error.message}.`
      : `❌ The code stopped before the tests could run: ${error?.name || "Error"}: ${error?.message || error}`);
    return 1;
  }
  try {
    vm.runInContext(fs.readFileSync("test_lesson.js", "utf8"), context, { filename: "test_lesson.js" });
  } catch (error) {
    console.log(`❌ The lesson's tests couldn't start: ${error?.name || "Error"}: ${error?.message || error}`);
    return 2;
  }
  if (!tests.length) {
    console.log("❌ The lesson has no tests (test(\"…\", () => { … })).");
    return 2;
  }
  let passed = 0;
  for (const { name, run } of tests) {
    try {
      vm.runInContext("__run()", Object.assign(context, { __run: run }), { timeout: 5000 });
      passed += 1;
      console.log(`✅ ${name}`);
    } catch (error) {
      const why = error?.name === "TestFailure" ? error.message : `the code stopped with ${error?.name || "Error"}: ${error?.message || error}`;
      console.log(`❌ ${name}: ${why}`);
    }
  }
  console.log("");
  console.log(`${passed === tests.length ? "🎉 " : ""}${passed} of ${tests.length} tests passed.`);
  return passed === tests.length ? 0 : 1;
}

process.exitCode = main();
